import time

class SensorReader:
    def __init__(self):
        self.last_temp = None
        self.last_humidity = None

    def read_loop(self):
        while True:
            temp = self._read_temperature()
            humidity = self._read_humidity()
            time.sleep(1)

    def _read_temperature(self):
        # read from hardware
        return 23.5

    def _read_humidity(self):
        # read from hardware
        return 45.0

# Consumer: polling instead of being notified
class DisplayPanel:
    def __init__(self, sensor: SensorReader):
        self.sensor = sensor

    def update_loop(self):
        last = None
        while True:
            if self.sensor.last_temp != last:
                self.render(self.sensor.last_temp)
                last = self.sensor.last_temp
            time.sleep(0.5)

class DataLogger:
    def __init__(self, sensor: SensorReader):
        self.sensor = sensor

    def poll_loop(self):
        last_temp = None
        while True:
            if self.sensor.last_temp != last_temp:
                self.log(self.sensor.last_temp)
                last_temp = self.sensor.last_temp
            time.sleep(0.5)
